local function b64decode(data)
	local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	local lookup = {}
	for i = 1, #chars do lookup[chars:byte(i)] = i - 1 end
	local out, n = {}, 0
	local buf, bits = 0, 0
	for i = 1, #data do
		local v = lookup[data:byte(i)]
		if v then
			buf = buf * 64 + v
			bits = bits + 6
			if bits >= 8 then
				bits = bits - 8
				local div = 2 ^ bits
				local byte = math.floor(buf / div)
				buf = buf - byte * div
				n = n + 1
				out[n] = string.char(byte)
				if n % 4096 == 0 then out[n] = out[n] end
			end
		end
	end
	return table.concat(out)
end

if writefile and isfile then
	for name, data in pairs(embedded) do
		if not isfile(name) then
			pcall(function() writefile(name, b64decode(data)) end)
		end
	end
end

local function resolveBackground(entry)
	if getcustomasset and isfile and entry.file and isfile(entry.file) then
		local ok, asset = pcall(getcustomasset, entry.file)
		if ok and asset then return asset end
	end
	return "rbxassetid://" .. entry.id
end

local function saveConfig()
	if writefile then
		pcall(function()
			writefile("antiBat_config.json", HttpService:JSONEncode(config))
		end)
	end
end

local function loadConfig()
	if isfile and isfile("antiBat_config.json") then
		local ok, data = pcall(function()
			return HttpService:JSONDecode(readfile("antiBat_config.json"))
		end)
		if ok and type(data) == "table" then
			if type(data.Keybind) == "string" then config.Keybind = data.Keybind end
			if type(data.AntiBatEnabled) == "boolean" then config.AntiBatEnabled = data.AntiBatEnabled end
			if type(data.InfJumpEnabled) == "boolean" then config.InfJumpEnabled = data.InfJumpEnabled end
			if type(data.BackgroundId) == "string" then config.BackgroundId = data.BackgroundId end
			if type(data.BackgroundIndex) == "number" then config.BackgroundIndex = data.BackgroundIndex end
		end
	end
end
loadConfig()

-- Anti Bat (velocity desync)
local antiBatConn = nil
local antiBatActive = false

local function enableAntiBat()
	if antiBatConn then return end
	antiBatActive = true
	antiBatConn = RunService.Heartbeat:Connect(function()
		if not antiBatActive then return end
		local char = LocalPlayer.Character
		if not char then return end
		local hrp = char:FindFirstChild("HumanoidRootPart")
		if not hrp then return end
		local vel = hrp.Velocity
		local y = vel.Y
		hrp.Velocity = Vector3.new(math.random(-4000, 4000), y, math.random(-4000, 4000))
		RunService.RenderStepped:Wait()
		if hrp then
			hrp.Velocity = vel
		end
	end)
end

local function disableAntiBat()
	antiBatActive = false
	if antiBatConn then
		antiBatConn:Disconnect()
		antiBatConn = nil
	end
end

-- Infinite Jump
local infJumpConn = nil
local infJumpActive = false
local forceJump = false

local function enableInfJump()
	if infJumpConn then return end
	infJumpActive = true
	infJumpConn = RunService.Heartbeat:Connect(function()
		if not infJumpActive then return end
		local char = LocalPlayer.Character
		if not char then return end
		local humanoid = char:FindFirstChildOfClass("Humanoid")
		local hrp = char:FindFirstChild("HumanoidRootPart")
		if not humanoid or not hrp then return end
		if humanoid.Jump or forceJump then
			local vel = hrp.Velocity
			if vel.Y < 50 then
				hrp.Velocity = Vector3.new(vel.X, 50, vel.Z)
			end
		end
	end)
end

local function disableInfJump()
	infJumpActive = false
	if infJumpConn then
		infJumpConn:Disconnect()
		infJumpConn = nil
	end
end

local function onJumping()
	if infJumpActive then
		forceJump = true
		task.wait(0.1)
		forceJump = false
	end
end

LocalPlayer.CharacterAdded:Connect(function(char)
	task.wait(0.5)
	local humanoid = char:FindFirstChildOfClass("Humanoid")
	if humanoid then
		humanoid.Jumping:Connect(onJumping)
	end
	if infJumpActive then
		enableInfJump()
	end
end)

if LocalPlayer.Character then
	local humanoid = LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
	if humanoid then
		humanoid.Jumping:Connect(onJumping)
	end
end

